<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowRight, ArrowUpRight, Upload, Users, BookOpen, ClipboardCheck, Repeat2, FileText, ScanLine, Plus, Check, Sparkles, Clock3 } from 'lucide-vue-next'
import { api,patch,session,statusName,dateText } from '../api'
import EmptyState from '../components/EmptyState.vue'
const router=useRouter(),data=ref<any>(null),error=ref('')
const date=new Date().toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'})
async function load(){try{data.value=await api('dashboard/')}catch(e:any){error.value=e.message}}
onMounted(load)
async function finish(plan:any){try{await patch(`plans/${plan.id}/`,{completed:true});await load()}catch(e:any){error.value=e.message}}
</script>
<template><div class="page-heading"><div><p class="eyebrow">TEACHING OVERVIEW</p><h1>教学概览<span class="heading-dot">.</span></h1><p class="subtitle">{{date}}<span class="separator">/</span>每一次进步，都从一次认真观察开始。</p></div><RouterLink to="/imports?new=1" class="button primary"><Plus :size="18"/>录入新资料</RouterLink></div><div v-if="error" class="notice danger">{{error}}</div>
 <template v-if="data"><section class="welcome-panel"><div><span class="welcome-kicker"><span class="live-dot"></span>你的教学，正在有序生长</span><h2>{{session.user.name}}，今天也一起<br/>把练习变成进步。</h2><p>整理作业、看见薄弱点，为下一次课做好准备。</p><RouterLink to="/grading" class="button cream">进入批改工作台<ArrowUpRight :size="17"/></RouterLink></div><div class="welcome-art" aria-hidden="true"><div class="art-orbit orbit-one"></div><div class="art-orbit orbit-two"></div><div class="art-sheet back"><div></div><div></div><span>Δ</span></div><div class="art-sheet front"><span class="art-caption">LEARNING, IN PROGRESS</span><div class="art-equation">ƒ(x) = x² + 2x</div><div class="art-lines"><i></i><i></i><i></i></div><div class="art-check"><Check :size="24"/></div><span class="art-graph">↗</span></div><span class="art-spark">✳</span><span class="art-floating"><Repeat2 :size="15"/>每一次，都更进一步</span></div></section>
 <section class="stats-grid"><RouterLink to="/students" class="stat-card"><div class="stat-label">在读学生<Users :size="18"/></div><div class="stat-number">{{data.students}}<small>位</small></div><p>每一位，都有专属学习轨迹<ArrowUpRight :size="15"/></p></RouterLink><RouterLink to="/questions" class="stat-card"><div class="stat-label">已审核题库<BookOpen :size="18"/></div><div class="stat-number">{{data.questions}}<small>道</small></div><p>持续积累你的教学资产<ArrowUpRight :size="15"/></p></RouterLink><RouterLink to="/grading" class="stat-card"><div class="stat-label">待批改题目<ClipboardCheck :size="18"/></div><div class="stat-number">{{data.pending_grades}}<small>题</small><span v-if="data.pending_grades" class="tiny-indicator">待处理</span></div><p>识别、复核与评分一站完成<ArrowUpRight :size="15"/></p></RouterLink><RouterLink to="/mistakes" class="stat-card"><div class="stat-label">待巩固错题<Repeat2 :size="18"/></div><div class="stat-number">{{data.active_mistakes}}<small>道</small></div><p>把薄弱点变成下一步的重点<ArrowUpRight :size="15"/></p></RouterLink></section>
 <div class="dashboard-columns"><div><section class="panel"><header class="panel-heading"><div><h2>从这里开始</h2><p>三种录入方式，接住每一种教学资料</p></div><span class="section-index">01 — IMPORT</span></header><div class="import-options"><RouterLink to="/imports?new=1&route=external" class="import-option"><span class="option-icon peach"><FileText :size="23"/></span><h3>外部试卷</h3><p>学校试卷、自主组卷<br/>有无答案，都能录入</p><span class="option-link">导入试卷<ArrowRight :size="16"/></span></RouterLink><RouterLink to="/imports?new=1&route=card" class="import-option"><span class="option-icon mint"><ScanLine :size="23"/></span><h3>规范答题卡</h3><p>定位识别，批量处理<br/>适合日常作业与测验</p><span class="option-link">上传答题卡<ArrowRight :size="16"/></span></RouterLink><RouterLink to="/imports?new=1&route=fragment" class="import-option"><span class="option-icon lavender"><Upload :size="23"/></span><h3>作业与零散错题</h3><p>拍照上传，自动切题<br/>留住每一个学习线索</p><span class="option-link">收集错题<ArrowRight :size="16"/></span></RouterLink></div></section>
 <section class="panel recent-panel"><header class="panel-heading"><div><h2>最近录入</h2><p>从原始资料，到有用的学习记录</p></div><RouterLink to="/imports" class="text-button">全部记录<ArrowRight :size="15"/></RouterLink></header><div v-if="data.recent_batches.length" class="table-scroll"><table><thead><tr><th>资料名称</th><th>学生 / 用途</th><th>状态</th><th>录入时间</th><th></th></tr></thead><tbody><tr v-for="batch in data.recent_batches" :key="batch.id" @click="router.push('/imports/'+batch.id)"><td><div class="file-cell"><span class="file-icon"><FileText :size="18"/></span><strong>{{batch.title}}</strong></div></td><td>{{batch.student_name||'题库资料'}}</td><td><span class="status" :class="batch.status">{{statusName[batch.status]}}</span></td><td class="muted">{{dateText(batch.created_at)}}</td><td><ArrowUpRight :size="16"/></td></tr></tbody></table></div><EmptyState v-else title="教学资料，从第一份开始" text="上传试卷或作业，建立你的教学资料库。"/></section></div>
 <aside class="dashboard-aside"><section class="panel todo-panel"><header class="panel-heading"><div><h2>教学待办<span class="count-badge">{{data.plans.length}}</span></h2><p>把下一次课的重点，提前准备好</p></div><Clock3 :size="19" class="muted"/></header><div v-for="plan in data.plans" :key="plan.id" class="todo"><button class="todo-check" aria-label="标记完成" @click="finish(plan)"></button><div><RouterLink :to="'/students/'+plan.student">{{plan.title}}</RouterLink><p>{{plan.goal||'学习计划'}}<span>· {{dateText(plan.due_date)}}</span></p></div></div><EmptyState v-if="!data.plans.length" title="今天的安排，由你定义" text="在学生档案中添加下一步学习计划。"/><RouterLink to="/students" class="todo-footer">前往学生档案添加计划<ArrowRight :size="15"/></RouterLink></section><section class="learning-note"><span class="eyebrow">THE LEARNING LOOP</span><h3>做对一道题，<br/>也读懂一种思路。</h3><div class="loop-steps"><span>发现问题</span><i></i><span>针对练习</span><i></i><span>复测验证</span></div><RouterLink to="/mistakes">查看错题与复练<ArrowUpRight :size="16"/></RouterLink><span class="note-art">↺</span></section><div class="ai-caption"><Sparkles :size="17"/><p>{{data.ai.configured?'AI识别服务已配置':'AI识别服务尚未配置'}}<small>答案与解答题评分始终经过教师确认</small></p><RouterLink to="/settings"><ArrowUpRight :size="16"/></RouterLink></div></aside></div>
 </template><div v-else-if="!error" class="loading">正在加载教学概览…</div>
</template>
